const data = require('fs').readFileSync(0, 'utf8').trim().split(/\s+/);
let x = parseInt(data[0], 10);
let n = BigInt(data[1]);
const MOD = 1000000007n;

function power(b, e, m) {
  b %= m;
  let r = 1n;
  while (e > 0n) {
    if (e & 1n) r = r * b % m;
    b = b * b % m;
    e >>= 1n;
  }
  return r;
}

let primes = [];
let t = x;
for (let d = 2; d * d <= t; d++) {
  if (t % d === 0) {
    primes.push(BigInt(d));
    while (t % d === 0) t /= d;
  }
}
if (t > 1) primes.push(BigInt(t));

let ans = 1n;
for (const p of primes) {
  let total = 0n;
  let pk = p;
  while (pk <= n) {
    total += n / pk;
    if (pk > n / p) break;
    pk *= p;
  }
  ans = ans * power(p, total, MOD) % MOD;
}

console.log(ans.toString());
